#include <bits/stdc++.h>
using namespace std;using LL=long long;using G=vector<unsigned>;using Sig=array<LL,6>;
void need(bool b,string s){if(!b)throw runtime_error(s);}
G tour(int n,unsigned c){G a(n);int k=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++,k++)if(c>>k&1)a[i]|=1u<<j;else a[j]|=1u<<i;return a;}
vector<Sig> literal(const G&a){int n=a.size();vector<int>p(n);iota(p.begin(),p.end(),0);LL H=0,C=0;vector<LL>E(n),S(n),Q(n),L(n);do{vector<bool>edge(n-1);for(int i=0;i<n-1;i++)edge[i]=a[p[i]]>>p[i+1]&1;bool full=true;for(bool b:edge)full&=b;if(full){H++;S[p[0]]++;E[p.back()]++;}for(int cut=0;cut<=n;cut++){bool ok=true;for(int j=0;j<n-1;j++)if(j!=cut-1&&!edge[j])ok=false;if(ok){C++;if(cut>0){Q[p[0]]++;L[p[cut-1]]++;}}}}while(next_permutation(p.begin(),p.end()));vector<Sig>z;for(int r=0;r<n;r++)z.push_back({H,E[r],S[r],Q[r],L[r],C});return z;}
array<LL,4> step(array<LL,4>s,bool Z){auto[h,e,R,d]=s;return Z?array<LL,4>{h+R-e,d,2*R-d,d}:array<LL,4>{h,0,2*R,d};}
array<LL,4> prefix(int q){array<LL,4>s={1,1,1,1};if(!q)return s;for(int j=31-__builtin_clz((unsigned)q);j>=0;j--)s=step(s,!(q>>j&1));return s;}
array<LL,4> suffix(array<LL,4>s,int t){while(t){s=step(s,t&1);t>>=1;}return s;}
array<LL,4> corestep(array<LL,4>s,Sig sig){auto[h,e,R,d]=s;auto[H,E,S,Q,L,C]=sig;return {H*h-S*e+L*R,E*d,C*R-Q*d,H*d};}
G birth(G a,bool Z){int n=a.size();for(auto&x:a)x|=1u<<n;a.push_back(0);if(Z){a[0]^=1u<<n;a[n]|=1;}return a;}
G pregraph(int q){G a={0};if(q)for(int j=31-__builtin_clz((unsigned)q);j>=0;j--)a=birth(a,!(q>>j&1));return a;}
G sufgraph(G a,int t){while(t){a=birth(a,t&1);t>>=1;}return a;}
G sew(G a,const G&b,int r){int n=a.size();unsigned right=((1u<<b.size())-1)<<n;for(auto&x:a)x|=right;for(auto x:b)a.push_back(x<<n);a[0]^=1u<<(n+r);a[n+r]|=1;return a;}
LL dfsH(const G&a){int n=a.size();unsigned all=(1u<<n)-1;LL H=0;function<void(int,unsigned)>rec=[&](int v,unsigned mask){if(mask==all){H++;return;}unsigned q=a[v]&~mask;while(q){int u=__builtin_ctz(q);q&=q-1;rec(u,mask|(1u<<u));}};for(int v=0;v<n;v++)rec(v,1u<<v);return H;}
LL recursiveH(const G&a){int n=a.size();unsigned N=1u<<n;vector<LL>memo((size_t)N*n,-1);function<LL(unsigned,int)>rec=[&](unsigned S,int v)->LL{LL&z=memo[(size_t)S*n+v];if(z>=0)return z;if(S==(1u<<v))return z=1;z=0;unsigned rem=S^(1u<<v),q=a[v]&rem;while(q){int u=__builtin_ctz(q);q&=q-1;z+=rec(rem,u);}return z;};LL H=0;for(int v=0;v<n;v++)H+=rec(N-1,v);return H;}
int main(int argc,char**argv){int M=1000000;map<Sig,pair<G,int>>bank;LL graphs=0,roots=0;for(int n=1;n<=5;n++)for(unsigned code=0;code<(1u<<(n*(n-1)/2));code++){G a=tour(n,code);auto sigs=literal(a);graphs++;for(int r=0;r<n;r++){bank.emplace(sigs[r],make_pair(a,r));roots++;}}need(bank.size()==65&&graphs==1099&&roots==5405,"complete literal signature bank");vector<Sig>cores;for(auto&[s,ar]:bank)if(s[0]>1)cores.push_back(s);need(cores.size()==50,"nontransitive inventory");
vector<LL>F(2*M+1);for(int q=0;q<=2*M;q++){auto s=prefix(q);F[q]=s[0];need(s[1]==((q+1)&1)&&s[2]==q+1&&s[3]==1,"physical prefix inversion");}
vector<unsigned char>hits(M/2+1);for(int q=0;q<=2*M-2;q+=2)if(F[q]<=M)hits[F[q]/2]=1;LL plain=accumulate(hits.begin(),hits.end(),0LL),tested=0;vector<LL>per;
for(auto sig:cores){auto[H,E,S,Q,L,C]=sig;LL aa=C-Q-H;need(aa>0,"positive denominator");LL nt=0;for(int q=0;q<M/L;q++){auto mid=corestep({F[q],(q+1)&1,q+1,1},sig);for(int t=0;t<=M/((q+1)*aa);t++){nt++;LL N=mid[0]+(LL)t*(mid[2]-mid[3])+mid[3]*(F[t]-1)+(t&1)*(mid[3]-mid[1]);need(N>0&&(N&1),"odd physical scalar");if(N<=M)hits[N/2]=1;}}tested+=nt;per.push_back(nt);}
vector<int>missing;LL outputs=0;for(int n=1;n<=M;n+=2){if(hits[n/2])outputs++;else missing.push_back(n);}need(plain==249077&&outputs==499997&&missing==vector<int>{7,21,462661},"independent million support");if(argc>1){ofstream f(argv[1],ios::binary);f.write((char*)hits.data(),hits.size());}
LL actual=0;for(auto&[sig,ar]:bank)if(sig[0]>1){auto[a,r]=ar;for(int q=0;q<4;q++)for(int t=0;t<4;t++){G out=sufgraph(sew(pregraph(q),a,r),t);need(dfsH(out)==suffix(corestep(prefix(q),sig),t)[0],"literal small one-core word");actual++;}}
G a1={10,0,3,6},a2={8,1,3,6,15};Sig s1=literal(a1)[0],s2=literal(a2)[4];need(s1==Sig{3,0,1,6,3,24}&&s2==Sig{5,0,5,32,5,64},"escape literal signatures");auto middle=corestep(corestep(prefix(2),s1),s2);need(middle==array<LL,4>{415,0,4128,15},"escape middle");G out=sufgraph(sew(sew(pregraph(2),a1,0),a2,4),112);need(out.size()==19&&recursiveH(out)==462661&&suffix(middle,112)[0]==462661,"independent backwards subset escape count");need(dfsH(out)==462661,"literal escape Hamilton-word DFS");need(127LL*3643==462661&&462661%7,"composite nonseven gap");
cout<<"{\n \"status\":\"PASS\",\n \"literal_core_graphs\":"<<graphs<<",\n \"literal_rooted_candidates\":"<<roots<<",\n \"distinct_signatures\":65,\n \"nontransitive_signatures\":50,\n \"physical_prefix_states\":"<<F.size()<<",\n \"broader_bound_pairs_tested\":"<<tested<<",\n \"plain_support\":"<<plain<<",\n \"odd_support\":"<<outputs<<",\n \"missing\":[7,21,462661],\n \"actual_small_graphs\":"<<actual<<",\n \"escape_order\":19,\n \"escape_H\":462661,\n \"escape_rows\":[";for(int i=0;i<(int)out.size();i++)cout<<(i?",":"")<<out[i];cout<<"],\n \"signatures\":[";int ii=0;for(auto&[s,ar]:bank){cout<<(ii++?",":"")<<"[";for(int j=0;j<6;j++)cout<<(j?",":"")<<s[j];cout<<"]";}cout<<"]\n}\n";
}
